import { FC, useEffect } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { Icon } from '../icon'
import { Loading } from '../loading'

/**
 * Types
 */
import type { ToastProps, ToastType } from './types'

import './index.scss'

/**
 * Constants
 */
const ICON_MAP: Record<Exclude<ToastType, 'loading'>, string> = {
  success: 'check-circle-fill',
  error: 'close-circle-fill',
  warning: 'warning-circle',
  info: 'info-circle',
}

export const ToastView: FC<ToastProps> = ({
  open,
  type = 'info',
  content,
  position = 'center',
  duration = 2000,
  icon,
  mask = false,
  onClose,
}) => {
  /**
   * Effects
   */
  useEffect(() => {
    if (!open || duration <= 0) return
    const timer = setTimeout(() => onClose?.(), duration)
    return () => clearTimeout(timer)
  }, [duration, onClose, open])

  /**
   * Early Returns
   */
  if (!open) return null

  /**
   * Render Helpers
   */
  const renderIcon = () => {
    if (icon) return icon
    if (type === 'loading') {
      return <Loading type="spinner" size="md" color="#fff" />
    }
    const iconName = ICON_MAP[type]
    return iconName ? <Icon name={iconName} size={48} color="#fff" /> : null
  }

  return (
    <View className="ct-toast" catchMove={mask}>
      {mask && <View className="ct-toast__mask" />}
      <View
        className={classNames(
          'ct-toast__content',
          `ct-toast__content--${position}`
        )}
      >
        {renderIcon()}
        <Text className="ct-toast__text">{content}</Text>
      </View>
    </View>
  )
}
