import { Children, FC, isValidElement } from 'react'
import {
  Swiper as TaroSwiper,
  SwiperItem as TaroSwiperItem,
  View,
} from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'

/**
 * Types
 */
import type { SwiperProps as TaroSwiperProps } from '@tarojs/components'
import type { SwiperItemProps, SwiperProps } from './types'

import './index.scss'

/**
 * Internal Types
 */
type SwiperChangeEvent = Parameters<NonNullable<TaroSwiperProps['onChange']>>[0]

type SwiperComponent = FC<SwiperProps> & {
  Item: FC<SwiperItemProps>
}

/**
 * Sub Components
 */
export const SwiperItem: FC<SwiperItemProps> = ({ children, className }) => {
  return (
    <TaroSwiperItem className={classNames('ct-swiper-item', className)}>
      {children}
    </TaroSwiperItem>
  )
}

/**
 * Main Component
 */
export const Swiper: SwiperComponent = ({
  current: propCurrent,
  defaultCurrent = 0,
  autoplay = false,
  interval = 5000,
  duration = 500,
  loop = true,
  vertical = false,
  showIndicator = true,
  indicatorColor = 'rgba(0, 0, 0, 0.3)',
  indicatorActiveColor = 'var(--ct-color-primary)',
  onChange,
  children,
  className,
}) => {
  /**
   * Hooks
   */
  const [current, setCurrent] = useControllable({
    value: propCurrent,
    defaultValue: defaultCurrent,
    onChange,
  })

  /**
   * Derived Values
   */
  const count = Children.toArray(children).filter(isValidElement).length

  /**
   * Callbacks
   */
  const handleChange = (event: SwiperChangeEvent) => {
    setCurrent(event.detail.current)
  }

  return (
    <View className={classNames('ct-swiper', className)}>
      <TaroSwiper
        className="ct-swiper__container"
        current={current}
        autoplay={autoplay}
        interval={interval}
        duration={duration}
        circular={loop}
        vertical={vertical}
        indicatorDots={false}
        onChange={handleChange}
      >
        {children}
      </TaroSwiper>

      {showIndicator && count > 1 && (
        <View
          className={classNames('ct-swiper__indicator', {
            'ct-swiper__indicator--vertical': vertical,
          })}
        >
          {Array.from({ length: count }).map((_, index) => (
            <View
              key={index}
              className={classNames('ct-swiper__dot', {
                'ct-swiper__dot--active': index === current,
              })}
              style={{
                backgroundColor:
                  index === current ? indicatorActiveColor : indicatorColor,
              }}
            />
          ))}
        </View>
      )}
    </View>
  )
}

Swiper.Item = SwiperItem

export default Swiper
export type { SwiperItemProps, SwiperProps } from './types'
