import { FC, useMemo, useRef, useState } from 'react'
import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'

/**
 * Types
 */
import type { SliderProps } from './types'

import './index.scss'

/**
 * Internal Types
 */
type SliderValue = number | [number, number]

export const Slider: FC<SliderProps> = ({
  value: propValue,
  defaultValue = 0,
  min = 0,
  max = 100,
  step = 1,
  range = false,
  disabled = false,
  showMarks = false,
  marks,
  showTooltip = false,
  trackColor,
  activeColor,
  onChange,
  onAfterChange,
  className,
}) => {
  /**
   * Derived Values
   */
  const normalizedDefaultValue = useMemo<SliderValue>(() => {
    if (!range) return defaultValue ?? min
    if (Array.isArray(defaultValue)) return defaultValue
    const fallback = defaultValue !== undefined ? Number(defaultValue) : min
    return [min, fallback]
  }, [defaultValue, min, range])

  const normalizedPropValue = useMemo<SliderValue | undefined>(() => {
    if (!range) return propValue as number | undefined
    if (Array.isArray(propValue)) return propValue
    if (propValue === undefined) return undefined
    return [min, Number(propValue)]
  }, [min, propValue, range])

  /**
   * Hooks
   */
  const [value, setValue] = useControllable<SliderValue>({
    value: normalizedPropValue,
    defaultValue: normalizedDefaultValue,
    onChange,
  })

  /**
   * States
   */
  const trackId = useRef(`ct-slider-track-${Date.now()}`)
  const trackRectRef = useRef<{ left: number; width: number } | null>(null)
  const [dragging, setDragging] = useState(false)
  const [tooltipVisible, setTooltipVisible] = useState(false)

  /**
   * Render Helpers
   */
  const getPercent = (val: number) => ((val - min) / (max - min)) * 100

  const formatValue = (val: number) => {
    const aligned = Math.round((val - min) / step) * step + min
    return Math.max(min, Math.min(max, aligned))
  }

  const trackStyle = useMemo(() => {
    if (range) {
      const [v1, v2] = Array.isArray(value) ? value : [min, min]
      return {
        left: `${getPercent(v1)}%`,
        width: `${getPercent(v2) - getPercent(v1)}%`,
        backgroundColor: activeColor,
      }
    }
    return {
      width: `${getPercent(value as number)}%`,
      backgroundColor: activeColor,
    }
  }, [value, activeColor, range])

  /**
   * Callbacks
   */
  const handleTouchStart = (thumbIndex: number) => () => {
    if (disabled) return
    Taro.createSelectorQuery()
      .select(`#${trackId.current}`)
      .boundingClientRect()
      .exec((res) => {
        if (res[0]) {
          trackRectRef.current = { left: res[0].left, width: res[0].width }
        }
      })
    setDragging(true)
    setTooltipVisible(showTooltip)
  }

  const handleTouchMove = (thumbIndex: number) => (e: any) => {
    if (disabled || !dragging) return

    const touch = e.touches[0]
    const rect = trackRectRef.current
    if (!rect) return
      const { left, width } = rect
      const percent = Math.max(0, Math.min(1, (touch.clientX - left) / width))
      const newVal = formatValue(min + percent * (max - min))

      if (range) {
        const [v1, v2] = Array.isArray(value) ? value : [min, min]
        const newValue: [number, number] =
          thumbIndex === 0
            ? [Math.min(newVal, v2), v2]
            : [v1, Math.max(newVal, v1)]
        setValue(newValue)
      } else {
        setValue(newVal)
      }
  }

  const handleTouchEnd = () => {
    setDragging(false)
    setTooltipVisible(false)
    onAfterChange?.(value)
  }

  const renderThumb = (val: number, index: number) => (
    <View
      key={index}
      className={classNames('ct-slider__thumb', {
        'ct-slider__thumb--active': dragging,
      })}
      style={{ left: `${getPercent(val)}%` }}
      onTouchStart={handleTouchStart(index)}
      onTouchMove={handleTouchMove(index)}
      onTouchEnd={handleTouchEnd}
    >
      {tooltipVisible && (
        <View className="ct-slider__tooltip">
          <Text>{val}</Text>
        </View>
      )}
    </View>
  )

  return (
    <View className={classNames('ct-slider', { 'ct-slider--disabled': disabled }, className)}>
      <View
        className="ct-slider__track"
        id={trackId.current}
        style={trackColor ? { backgroundColor: trackColor } : undefined}
      >
        <View className="ct-slider__fill" style={trackStyle} />

        {range ? (
          <>
            {renderThumb((Array.isArray(value) ? value : [min, min])[0], 0)}
            {renderThumb((Array.isArray(value) ? value : [min, min])[1], 1)}
          </>
        ) : (
          renderThumb(value as number, 0)
        )}
      </View>

      {showMarks && marks && (
        <View className="ct-slider__marks">
          {Object.entries(marks).map(([key, label]) => (
            <View
              key={key}
              className="ct-slider__mark"
              style={{ left: `${getPercent(Number(key))}%` }}
            >
              <Text>{label}</Text>
            </View>
          ))}
        </View>
      )}
    </View>
  )
}

export default Slider
export type { SliderProps } from './types'
