import { FC, Fragment, useCallback, useMemo, useState } from 'react'
import { ScrollView, Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { Checkbox } from '../checkbox'
import { Icon } from '../icon'
import { Loading } from '../loading'
import { Radio } from '../radio'

/**
 * Types
 */
import type {
  TableColumn,
  TableExpandable,
  TableProps,
  TableRowSelection,
} from './types'

import './index.scss'

/**
 * Helpers
 */
const getRowKey = <T,>(record: T, rowKey: TableProps<T>['rowKey'], index: number): string => {
  if (typeof rowKey === 'function') {
    return rowKey(record)
  }
  if (typeof rowKey === 'string' && record) {
    return String((record as any)[rowKey])
  }
  return String(index)
}

const getCellValue = <T,>(record: T, column: TableColumn<T>, index: number): any => {
  if (column.render) {
    const value = column.dataIndex ? (record as any)[column.dataIndex] : record
    return column.render(value, record, index)
  }
  if (column.dataIndex) {
    return (record as any)[column.dataIndex]
  }
  return null
}

/**
 * Main Component
 */
export const Table: FC<TableProps> = <T extends object>({
  columns,
  dataSource,
  rowKey = 'id',
  size = 'md',
  bordered = false,
  stickyHeader = false,
  stickyTop = 0,
  expandable,
  rowSelection,
  emptyText = '暂无数据',
  loading = false,
  onRowClick,
  className,
  style,
  maxHeight,
  striped = false,
}: TableProps<T>) => {
  /**
   * States
   */
  const [innerExpandedKeys, setInnerExpandedKeys] = useState<string[]>(
    expandable?.defaultExpandedRowKeys || []
  )
  const [innerSelectedKeys, setInnerSelectedKeys] = useState<string[]>([])

  /**
   * Derived Values
   */
  const expandedKeys = expandable?.expandedRowKeys ?? innerExpandedKeys
  const selectedKeys = rowSelection?.selectedRowKeys ?? innerSelectedKeys

  const { fixedLeftColumns, fixedRightColumns, scrollColumns } = useMemo(() => {
    const left: TableColumn<T>[] = []
    const right: TableColumn<T>[] = []
    const scroll: TableColumn<T>[] = []

    columns.forEach((col) => {
      if (col.fixed === 'left') {
        left.push(col)
      } else if (col.fixed === 'right') {
        right.push(col)
      } else {
        scroll.push(col)
      }
    })

    return { fixedLeftColumns: left, fixedRightColumns: right, scrollColumns: scroll }
  }, [columns])

  const hasFixedLeft = fixedLeftColumns.length > 0
  const hasFixedRight = fixedRightColumns.length > 0

  const { isAllSelected, isIndeterminate } = useMemo(() => {
    if (!rowSelection || rowSelection.type === 'radio') {
      return { isAllSelected: false, isIndeterminate: false }
    }

    const selectableKeys = dataSource
      .map((record, index) => {
        const checkboxProps = rowSelection?.getCheckboxProps?.(record)
        if (checkboxProps?.disabled) return null
        return getRowKey(record, rowKey, index)
      })
      .filter(Boolean) as string[]

    const selectedCount = selectableKeys.filter((k) => selectedKeys.includes(k)).length
    return {
      isAllSelected: selectableKeys.length > 0 && selectedCount === selectableKeys.length,
      isIndeterminate: selectedCount > 0 && selectedCount < selectableKeys.length,
    }
  }, [dataSource, selectedKeys, rowSelection, rowKey])

  const tableStyle: React.CSSProperties = {
    ...style,
    ...(maxHeight ? { maxHeight: typeof maxHeight === 'number' ? `${maxHeight}rpx` : maxHeight } : {}),
  }

  /**
   * Callbacks
   */
  const handleExpand = useCallback((record: T, key: string) => {
    const newKeys = expandedKeys.includes(key)
      ? expandedKeys.filter((k) => k !== key)
      : [...expandedKeys, key]

    if (!expandable?.expandedRowKeys) {
      setInnerExpandedKeys(newKeys)
    }
    expandable?.onExpandChange?.(newKeys, record)
  }, [expandedKeys, expandable])

  const handleSelect = useCallback((record: T, key: string, checked: boolean) => {
    let newKeys: string[]
    if (rowSelection?.type === 'radio') {
      newKeys = checked ? [key] : []
    } else {
      newKeys = checked
        ? [...selectedKeys, key]
        : selectedKeys.filter((k) => k !== key)
    }

    if (!rowSelection?.selectedRowKeys) {
      setInnerSelectedKeys(newKeys)
    }

    const selectedRows = dataSource.filter((item, idx) =>
      newKeys.includes(getRowKey(item, rowKey, idx))
    )
    rowSelection?.onChange?.(newKeys, selectedRows)
  }, [selectedKeys, rowSelection, dataSource, rowKey])

  const handleSelectAll = useCallback((checked: boolean) => {
    const allKeys = dataSource
      .map((record, index) => {
        const checkboxProps = rowSelection?.getCheckboxProps?.(record)
        if (checkboxProps?.disabled) return null
        return getRowKey(record, rowKey, index)
      })
      .filter(Boolean) as string[]

    const newKeys = checked ? allKeys : []

    if (!rowSelection?.selectedRowKeys) {
      setInnerSelectedKeys(newKeys)
    }

    const selectedRows = checked ? dataSource.filter((_, idx) => {
      const checkboxProps = rowSelection?.getCheckboxProps?.(dataSource[idx])
      return !checkboxProps?.disabled
    }) : []
    rowSelection?.onChange?.(newKeys, selectedRows)
  }, [dataSource, rowKey, rowSelection])

  /**
   * Render Helpers
   */
  const renderHeaderCell = (column: TableColumn<T>, isFixed?: 'left' | 'right') => (
    <View
      key={column.key}
      className={classNames(
        'ct-table__header-cell',
        `ct-table__header-cell--${column.align || 'left'}`,
        {
          'ct-table__header-cell--fixed': isFixed,
          [`ct-table__header-cell--fixed-${isFixed}`]: isFixed,
        },
        column.className
      )}
      style={{ width: column.width }}
    >
      {column.title}
    </View>
  )

  const renderCell = (record: T, column: TableColumn<T>, index: number, isFixed?: 'left' | 'right') => (
    <View
      key={column.key}
      className={classNames(
        'ct-table__cell',
        `ct-table__cell--${column.align || 'left'}`,
        {
          'ct-table__cell--fixed': isFixed,
          [`ct-table__cell--fixed-${isFixed}`]: isFixed,
        },
        column.className
      )}
      style={{ width: column.width }}
    >
      {getCellValue(record, column, index)}
    </View>
  )

  const renderRow = (record: T, index: number) => {
    const key = getRowKey(record, rowKey, index)
    const isExpanded = expandedKeys.includes(key)
    const isSelected = selectedKeys.includes(key)
    const checkboxProps = rowSelection?.getCheckboxProps?.(record)

    return (
      <Fragment key={key}>
        <View
          className={classNames('ct-table__row', {
            'ct-table__row--striped': striped && index % 2 === 1,
            'ct-table__row--selected': isSelected,
            'ct-table__row--clickable': !!onRowClick,
          })}
          onClick={() => onRowClick?.(record, index)}
        >
          {rowSelection && (
            <View className="ct-table__cell ct-table__cell--selection">
              {rowSelection.type === 'radio' ? (
                <Radio
                  checked={isSelected}
                  disabled={checkboxProps?.disabled}
                  onChange={(checked) => handleSelect(record, key, checked)}
                />
              ) : (
                <Checkbox
                  checked={isSelected}
                  disabled={checkboxProps?.disabled}
                  onChange={(checked) => handleSelect(record, key, checked)}
                />
              )}
            </View>
          )}

          {expandable?.expandedRowRender && (
            <View
              className="ct-table__cell ct-table__cell--expand"
              onClick={(e) => {
                e.stopPropagation()
                handleExpand(record, key)
              }}
            >
              {expandable.expandIcon ? (
                expandable.expandIcon({ expanded: isExpanded, record })
              ) : (
                <View className={classNames('ct-table__expand-icon', { 'ct-table__expand-icon--expanded': isExpanded })}>
                  <Icon name="chevron-right" size={32} />
                </View>
              )}
            </View>
          )}

          {fixedLeftColumns.map((col) => renderCell(record, col, index, 'left'))}
          {scrollColumns.map((col) => renderCell(record, col, index))}
          {fixedRightColumns.map((col) => renderCell(record, col, index, 'right'))}
        </View>

        {expandable?.expandedRowRender && isExpanded && (
          <View className="ct-table__expanded-row">
            {expandable.expandedRowRender(record, index)}
          </View>
        )}
      </Fragment>
    )
  }

  return (
    <View
      className={classNames(
        'ct-table',
        `ct-table--${size}`,
        {
          'ct-table--bordered': bordered,
          'ct-table--sticky': stickyHeader,
          'ct-table--loading': loading,
          'ct-table--has-fixed-left': hasFixedLeft,
          'ct-table--has-fixed-right': hasFixedRight,
        },
        className
      )}
      style={tableStyle}
    >
      {loading && (
        <View className="ct-table__loading">
          <Loading size="md" />
        </View>
      )}

      <ScrollView
        className="ct-table__scroll"
        scrollX
        scrollY={!!maxHeight}
        enhanced
        showScrollbar={false}
      >
        <View
          className="ct-table__header"
          style={stickyHeader ? { top: `${stickyTop}rpx` } : undefined}
        >
          <View className="ct-table__header-row">
            {rowSelection && (
              <View className="ct-table__header-cell ct-table__header-cell--selection">
                {rowSelection.type !== 'radio' && (
                  <Checkbox
                    checked={isAllSelected}
                    indeterminate={isIndeterminate}
                    onChange={handleSelectAll}
                  />
                )}
              </View>
            )}

            {expandable?.expandedRowRender && (
              <View className="ct-table__header-cell ct-table__header-cell--expand" />
            )}

            {fixedLeftColumns.map((col) => renderHeaderCell(col, 'left'))}
            {scrollColumns.map((col) => renderHeaderCell(col))}
            {fixedRightColumns.map((col) => renderHeaderCell(col, 'right'))}
          </View>
        </View>

        <View className="ct-table__body">
          {dataSource.length > 0 ? (
            dataSource.map((record, index) => renderRow(record, index))
          ) : (
            <View className="ct-table__empty">
              <Text className="ct-table__empty-text">{emptyText}</Text>
            </View>
          )}
        </View>
      </ScrollView>
    </View>
  )
}

export default Table
export type {
  TableColumn,
  TableExpandable,
  TableProps,
  TableRowSelection,
  TableSize,
} from './types'
