import { FC, useState } from 'react'
import { Input, Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Icon } from '../icon'

/**
 * Types
 */
import type { InputProps } from '@tarojs/components'
import type { SearchBarProps } from './types'

import './index.scss'

/**
 * Internal Types
 */
type InputEvent = Parameters<NonNullable<InputProps['onInput']>>[0]
type FocusEvent = Parameters<NonNullable<InputProps['onFocus']>>[0]
type BlurEvent = Parameters<NonNullable<InputProps['onBlur']>>[0]

/**
 * Main Component
 */
export const SearchBar: FC<SearchBarProps> = ({
  value: propValue,
  defaultValue = '',
  placeholder = '搜索',
  showCancel = false,
  cancelText = '取消',
  autoFocus = false,
  disabled = false,
  clearable = true,
  icon,
  align = 'left',
  backgroundColor,
  onChange,
  onFocus,
  onBlur,
  onSearch,
  onCancel,
  onClear,
  className,
}) => {
  /**
   * Hooks
   */
  const [value, setValue] = useControllable({
    value: propValue,
    defaultValue,
    onChange,
  })

  /**
   * States
   */
  const [focused, setFocused] = useState(false)

  /**
   * Derived Values
   */
  const showClear = clearable && value && !disabled

  /**
   * Callbacks
   */
  const handleInput = (event: InputEvent) => {
    setValue(event.detail.value)
  }

  const handleFocus = (event: FocusEvent) => {
    setFocused(true)
    onFocus?.(event)
  }

  const handleBlur = (event: BlurEvent) => {
    setFocused(false)
    onBlur?.(event)
  }

  const handleClear = () => {
    setValue('')
    onClear?.()
  }

  const handleConfirm = () => {
    onSearch?.(value)
  }

  const handleCancel = () => {
    setValue('')
    setFocused(false)
    onCancel?.()
  }

  return (
    <View className={classNames('ct-search-bar', className)}>
      <View
        className={classNames('ct-search-bar__content', {
          'ct-search-bar__content--focused': focused,
        })}
        style={backgroundColor ? { backgroundColor } : undefined}
      >
        <View className="ct-search-bar__icon">
          {icon || (
            <Icon name="search" size={32} color="var(--ct-color-text-tertiary)" />
          )}
        </View>

        <Input
          className={classNames(
            'ct-search-bar__input',
            `ct-search-bar__input--${align}`,
          )}
          value={value}
          placeholder={placeholder}
          disabled={disabled}
          focus={autoFocus}
          confirmType="search"
          onInput={handleInput}
          onFocus={handleFocus}
          onBlur={handleBlur}
          onConfirm={handleConfirm}
        />

        {showClear && (
          <View className="ct-search-bar__clear" onClick={handleClear}>
            <Icon
              name="close-circle-fill"
              size={32}
              color="var(--ct-color-text-quaternary)"
            />
          </View>
        )}
      </View>

      {showCancel && (focused || value) && (
        <View className="ct-search-bar__cancel" onClick={handleCancel}>
          <Text>{cancelText}</Text>
        </View>
      )}
    </View>
  )
}

export default SearchBar
export type { SearchBarProps } from './types'
