import { FC } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'

/**
 * Types
 */
import type { LoadingProps } from './types'

import './index.scss'

/**
 * Constants
 */
const SIZE_MAP = { sm: 32, md: 48, lg: 64 }

export const Loading: FC<LoadingProps> = ({
  type = 'spinner',
  size = 'md',
  color,
  text,
  direction = 'horizontal',
  className,
}) => {
  /**
   * Derived Values
   */
  const iconSize = SIZE_MAP[size]
  const showSpinner = type === 'spinner' || type === 'circular'

  return (
    <View
      className={classNames('ct-loading', `ct-loading--${direction}`, className)}
    >
      {showSpinner && (
        <View
          className={classNames('ct-loading__spinner', {
            'ct-loading__spinner--circular': type === 'circular',
          })}
          style={{
            width: `${iconSize}rpx`,
            height: `${iconSize}rpx`,
            borderTopColor: color,
          }}
        />
      )}
      {type === 'dots' && (
        <View className="ct-loading__dots">
          {[0, 1, 2].map((i) => (
            <View
              key={i}
              className="ct-loading__dot"
              style={{
                backgroundColor: color,
                animationDelay: `${i * 0.15}s`,
              }}
            />
          ))}
        </View>
      )}
      {text && <Text className="ct-loading__text">{text}</Text>}
    </View>
  )
}

export default Loading
export type { LoadingProps, LoadingType, LoadingSize } from './types'
