import { Children, FC, isValidElement, useEffect, useState } from 'react'
import { ScrollView, Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Badge } from '../badge'

/**
 * Types
 */
import type { TabItem, TabPanelProps, TabsProps } from './types'

import './index.scss'

/**
 * Sub Components
 */
export const TabPanel: FC<TabPanelProps> = ({ children, className }) => {
  return <View className={classNames('ct-tabs__panel', className)}>{children}</View>
}

/**
 * Internal Types
 */
type TabsComponent = FC<TabsProps> & {
  Panel: FC<TabPanelProps>
}

/**
 * Main Component
 */
export const Tabs: TabsComponent = ({
  activeKey: propActiveKey,
  defaultActiveKey,
  variant = 'line',
  items,
  onChange,
  scrollable = false,
  showIndicator = true,
  indicatorWidth = 'auto',
  className,
  children,
}) => {
  /**
   * Hooks
   */
  const [activeKey, setActiveKey] = useControllable<string | undefined>({
    value: propActiveKey,
    defaultValue: defaultActiveKey ?? items[0]?.key,
    onChange,
  })

  /**
   * States
   */
  const [indicatorStyle, setIndicatorStyle] = useState<React.CSSProperties>({})

  /**
   * Derived Values
   */
  const shouldShowIndicator = showIndicator && variant === 'line'

  const activePanel = Children.toArray(children).find((child) => {
    if (isValidElement(child) && child.props.tabKey === activeKey) {
      return true
    }
    return false
  })

  /**
   * Callbacks
   */
  const handleTabClick = (item: TabItem) => {
    if (item.disabled) return
    setActiveKey(item.key)
  }

  /**
   * Effects
   */
  useEffect(() => {
    if (!shouldShowIndicator || !activeKey || !items.length) return

    Taro.nextTick(() => {
      const query = Taro.createSelectorQuery()
      query.select(`.ct-tabs__item--active`).boundingClientRect()
      query.select(`.ct-tabs__nav`).boundingClientRect()
      query.exec((res) => {
        if (res[0] && res[1]) {
          const tabRect = res[0]
          const navRect = res[1]
          const left = tabRect.left - navRect.left
          const width = indicatorWidth === 'auto' ? tabRect.width : indicatorWidth

          setIndicatorStyle({
            width: typeof width === 'number' ? `${width}px` : width,
            transform: `translateX(${left}px)`,
          })
        }
      })
    })
  }, [activeKey, indicatorWidth, shouldShowIndicator])

  /**
   * Render Helpers
   */
  const NavContent = (
    <View className="ct-tabs__nav">
      {items.map((item) => (
        <View
          key={item.key}
          className={classNames('ct-tabs__item', {
            'ct-tabs__item--active': activeKey === item.key,
            'ct-tabs__item--disabled': item.disabled,
          })}
          hoverClass={item.disabled ? 'none' : 'ct-clickable--hover'}
          onClick={() => handleTabClick(item)}
        >
          <Text className="ct-tabs__item-text">{item.title}</Text>
          {item.badge !== undefined && (
            <Badge content={item.badge} className="ct-tabs__badge" />
          )}
        </View>
      ))}

      {shouldShowIndicator && (
        <View className="ct-tabs__indicator" style={indicatorStyle} />
      )}
    </View>
  )

  return (
    <View className={classNames('ct-tabs', `ct-tabs--${variant}`, className)}>
      {scrollable ? (
        <ScrollView scrollX className="ct-tabs__scroll">
          {NavContent}
        </ScrollView>
      ) : (
        <View className="ct-tabs__header">{NavContent}</View>
      )}

      <View className="ct-tabs__content">{activePanel}</View>
    </View>
  )
}

Tabs.Panel = TabPanel

export default Tabs
export type { TabsProps, TabPanelProps, TabItem, TabsVariant } from './types'
