import { Children, FC, createContext, useContext } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { Badge } from '../badge'

/**
 * Types
 */
import type { GridItemProps, GridProps } from './types'

import './index.scss'

/**
 * Internal Types
 */
interface GridContextValue {
  columns: number
  gutter: number
  center: boolean
  iconSize: number
}

/**
 * Context
 */
const GridContext = createContext<GridContextValue | null>(null)

/**
 * Sub Components
 */
export const GridItem: FC<GridItemProps> = ({
  icon,
  text,
  badge,
  dot,
  onClick,
  children,
  className,
  iconSize,
}) => {
  /**
   * Hooks
   */
  const context = useContext(GridContext)

  /**
   * Derived Values
   */
  const columns = context?.columns ?? 1
  const gutter = context?.gutter ?? 0
  const center = context?.center ?? true
  const itemWidth = `${100 / columns}%`
  const resolvedIconSize = iconSize ?? context?.iconSize ?? 56
  const isClickable = !!onClick

  return (
    <View
      className={classNames(
        'ct-grid__item',
        {
          'ct-grid__item--center': center,
        },
        className,
      )}
      style={{
        width: itemWidth,
        padding: gutter ? `${gutter / 2}rpx` : undefined,
      }}
      hoverClass={isClickable ? 'ct-clickable--hover' : 'none'}
      onClick={onClick}
    >
      <View className="ct-grid__item-content">
        {children ||
          (icon && (
            <View
              className="ct-grid__icon"
              style={{ fontSize: `${resolvedIconSize}rpx` }}
            >
              {icon}
              {(badge !== undefined || dot) && (
                <Badge
                  content={badge}
                  dot={dot}
                  className="ct-grid__badge"
                />
              )}
            </View>
          ))}
        {!children && text && <Text className="ct-grid__text">{text}</Text>}
      </View>
    </View>
  )
}

/**
 * Internal Types
 */
type GridComponent = FC<GridProps> & {
  Item: FC<GridItemProps>
}

/**
 * Main Component
 */
export const Grid: GridComponent = ({
  columns = 4,
  items = [],
  bordered = true,
  square = false,
  iconSize = 56,
  gutter = 0,
  center = true,
  children,
  className,
}) => {
  /**
   * Derived Values
   */
  const wrapperStyle = gutter ? { padding: `${gutter / 2}rpx` } : undefined
  const hasChildren = Children.count(children) > 0

  return (
    <GridContext.Provider value={{ columns, gutter, center, iconSize }}>
      <View
        className={classNames(
          'ct-grid',
          {
            'ct-grid--bordered': bordered,
            'ct-grid--square': square,
          },
          className,
        )}
        style={wrapperStyle}
      >
        {hasChildren
          ? children
          : items.map((item, index) => (
              <GridItem
                key={index}
                icon={item.icon}
                text={item.text}
                badge={item.badge}
                dot={item.dot}
                onClick={item.onClick}
              />
            ))}
      </View>
    </GridContext.Provider>
  )
}

Grid.Item = GridItem

export default Grid
export type { GridProps, GridItemProps } from './types'
