import { FC, useCallback, useMemo } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Icon } from '../icon'

/**
 * Types
 */
import type { SelectorOption, SelectorProps } from './types'

import './index.scss'

export const Selector: FC<SelectorProps> = ({
  options,
  value,
  defaultValue,
  multiple = false,
  columns,
  disabled = false,
  showCheckMark = true,
  onChange,
  className,
}) => {
  /**
   * Hooks
   */
  const [internalValue, setInternalValue] = useControllable<
    (string | number) | (string | number)[] | undefined
  >({
    value,
    defaultValue: defaultValue ?? (multiple ? [] : undefined),
  })

  /**
   * Derived Values
   */
  const selectedValues = useMemo(() => {
    if (internalValue === undefined || internalValue === null) return []
    return Array.isArray(internalValue) ? internalValue : [internalValue]
  }, [internalValue])

  const gridStyle = columns
    ? {
        gridTemplateColumns: `repeat(${columns}, 1fr)`,
      }
    : undefined

  /**
   * Render Helpers
   */
  const isSelected = useCallback(
    (val: string | number) => {
      return selectedValues.includes(val)
    },
    [selectedValues]
  )

  /**
   * Callbacks
   */
  const handleOptionClick = useCallback(
    (option: SelectorOption) => {
      if (disabled || option.disabled) return

      const val = option.value
      let newValue: (string | number) | (string | number)[]
      let newOptions: SelectorOption | SelectorOption[]

      if (multiple) {
        if (isSelected(val)) {
          newValue = selectedValues.filter((v) => v !== val)
          newOptions = options.filter((opt) => (newValue as (string | number)[]).includes(opt.value))
        } else {
          newValue = [...selectedValues, val]
          newOptions = options.filter((opt) => (newValue as (string | number)[]).includes(opt.value))
        }
      } else {
        if (isSelected(val)) {
          newValue = undefined as any
          newOptions = undefined as any
        } else {
          newValue = val
          newOptions = option
        }
      }

      setInternalValue(newValue)
      onChange?.(newValue, newOptions)
    },
    [disabled, multiple, isSelected, selectedValues, options, setInternalValue, onChange]
  )

  return (
    <View
      className={classNames(
        'ct-selector',
        {
          'ct-selector--disabled': disabled,
          'ct-selector--grid': columns,
        },
        className
      )}
      style={gridStyle}
    >
      {options.map((option) => {
        const selected = isSelected(option.value)

        return (
          <View
            key={option.value}
            className={classNames('ct-selector__item', {
              'ct-selector__item--selected': selected,
              'ct-selector__item--disabled': option.disabled,
            })}
            onClick={() => handleOptionClick(option)}
          >
            <View className="ct-selector__item-content">
              <Text className="ct-selector__item-label">{option.label}</Text>
              {option.description && (
                <Text className="ct-selector__item-description">{option.description}</Text>
              )}
            </View>
            {showCheckMark && selected && (
              <View className="ct-selector__check">
                <Icon name="check" size={24} className="ct-selector__check-icon" />
              </View>
            )}
          </View>
        )
      })}
    </View>
  )
}

export default Selector
export type { SelectorProps, SelectorOption } from './types'
