import { FC, Fragment } from 'react'
import { View } from '@tarojs/components'
import classNames from 'classnames'

/**
 * Types
 */
import type { SkeletonBlockProps, SkeletonProps } from './types'

import './index.scss'

export const SkeletonBlock: FC<SkeletonBlockProps> = ({
  width = '100%',
  height = 32,
  round = false,
  animated = true,
  className,
}) => {
  /**
   * Derived Values
   */
  const style = {
    width: typeof width === 'number' ? `${width}rpx` : width,
    height: typeof height === 'number' ? `${height}rpx` : height,
  }

  return (
    <View
      className={classNames(
        'ct-skeleton__block',
        {
          'ct-skeleton__block--animated': animated,
          'ct-skeleton__block--round': round,
        },
        className
      )}
      style={style}
    />
  )
}

/**
 * Internal Types
 */
type SkeletonComponent = FC<SkeletonProps> & {
  Block: FC<SkeletonBlockProps>
}

export const Skeleton: SkeletonComponent = ({
  loading = true,
  animated = true,
  rows = 3,
  avatar = false,
  avatarShape = 'circle',
  avatarSize = 80,
  title = true,
  titleWidth = '40%',
  rowsWidth,
  children,
  className,
}) => {
  /**
   * Derived Values
   */
  const showTitle = title && rows > 0

  /**
   * Render Helpers
   */
  const getRowWidth = (index: number) => {
    if (rowsWidth && rowsWidth[index]) {
      return rowsWidth[index]
    }
    if (index === rows - 1) {
      return '60%'
    }
    return '100%'
  }

  /**
   * Early Returns
   */
  if (!loading) {
    return <Fragment>{children}</Fragment>
  }

  return (
    <View className={classNames('ct-skeleton', className)}>
      {avatar && (
        <View className="ct-skeleton__avatar">
          <SkeletonBlock
            width={avatarSize}
            height={avatarSize}
            round={avatarShape === 'circle'}
            animated={animated}
          />
        </View>
      )}

      <View className="ct-skeleton__content">
        {showTitle && (
          <SkeletonBlock
            width={titleWidth}
            height={40}
            animated={animated}
            className="ct-skeleton__title"
          />
        )}

        {rows > 0 &&
          Array.from({ length: rows }).map((_, index) => (
            <SkeletonBlock
              key={index}
              width={getRowWidth(index)}
              height={32}
              animated={animated}
              className="ct-skeleton__row"
            />
          ))}
      </View>
    </View>
  )
}

Skeleton.Block = SkeletonBlock

export default Skeleton
export type { SkeletonProps, SkeletonBlockProps } from './types'
