import React, { FC, useCallback, useEffect, useMemo, useState } from 'react'
import { ScrollView, Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { BottomSheet } from '../bottom-sheet'
import { Icon } from '../icon'

/**
 * Types
 */
import type { CascaderOption, CascaderProps } from './types'

import './index.scss'

export const Cascader: FC<CascaderProps> = ({
  open,
  options,
  value,
  defaultValue,
  title,
  placeholder = '请选择',
  confirmText = '确定',
  cancelText = '取消',
  onChange,
  onConfirm,
  onCancel,
  onClose,
  resetOnClose = true,
  className,
  renderOption,
}) => {
  /**
   * Hooks
   */
  const [internalValue, setInternalValue] = useControllable<(string | number)[]>({
    value,
    defaultValue: defaultValue || [],
  })

  /**
   * States
   */
  const [tempValue, setTempValue] = useState<(string | number)[]>([])
  const [activeLevel, setActiveLevel] = useState(0)

  /**
   * Effects
   */
  useEffect(() => {
    if (open) {
      setTempValue(internalValue || [])
      const level = internalValue?.length || 0
      setActiveLevel(Math.max(0, level > 0 ? level - 1 : 0))
    }
  }, [open, internalValue])

  /**
   * Derived Values
   */
  const levelOptions = useMemo(() => {
    const levels: CascaderOption[][] = [options]
    let currentOptions = options

    for (const val of tempValue) {
      const selected = currentOptions.find((opt) => opt.value === val)
      if (selected?.children && selected.children.length > 0) {
        levels.push(selected.children)
        currentOptions = selected.children
      } else {
        break
      }
    }

    return levels
  }, [options, tempValue])

  const selectedOptions = useMemo(() => {
    const result: CascaderOption[] = []
    let currentOptions = options

    for (const val of tempValue) {
      const selected = currentOptions.find((opt) => opt.value === val)
      if (selected) {
        result.push(selected)
        if (selected.children) {
          currentOptions = selected.children
        } else {
          break
        }
      } else {
        break
      }
    }

    return result
  }, [options, tempValue])

  /**
   * Callbacks
   */
  const handleOptionClick = useCallback(
    (option: CascaderOption, level: number) => {
      if (option.disabled) return

      const newValue = [...tempValue.slice(0, level), option.value]
      setTempValue(newValue)

      if (option.children && option.children.length > 0) {
        setActiveLevel(level + 1)
      } else {
        setActiveLevel(level)
      }
    },
    [tempValue]
  )

  const handleTabClick = useCallback((level: number) => {
    setActiveLevel(level)
  }, [])

  const handleConfirm = useCallback(() => {
    setInternalValue(tempValue)
    onChange?.(tempValue, selectedOptions)
    onConfirm?.(tempValue, selectedOptions)
    onClose?.()
  }, [tempValue, selectedOptions, setInternalValue, onChange, onConfirm, onClose])

  const handleCancel = useCallback(() => {
    if (resetOnClose) {
      setTempValue(internalValue || [])
    }
    onCancel?.()
    onClose?.()
  }, [resetOnClose, internalValue, onCancel, onClose])

  const handleClose = useCallback(() => {
    if (resetOnClose) {
      setTempValue(internalValue || [])
    }
    onClose?.()
  }, [resetOnClose, internalValue, onClose])

  /**
   * Render Helpers
   */
  const renderTabs = () => {
    const tabs: React.ReactNode[] = []

    for (let i = 0; i <= Math.min(activeLevel, levelOptions.length - 1); i++) {
      const selected = selectedOptions[i]
      const isActive = i === activeLevel
      const isPlaceholder = !selected

      tabs.push(
        <View
          key={i}
          className={classNames('ct-cascader__tab', {
            'ct-cascader__tab--active': isActive,
          })}
          onClick={() => handleTabClick(i)}
        >
          <Text
            className={classNames('ct-cascader__tab-text', {
              'ct-cascader__tab-text--placeholder': isPlaceholder,
            })}
          >
            {selected?.label || placeholder}
          </Text>
          {isActive && <View className="ct-cascader__tab-line" />}
        </View>
      )
    }

    return tabs
  }

  const renderOptions = (opts: CascaderOption[], level: number) => {
    const currentValue = tempValue[level]

    return opts.map((option) => {
      const isSelected = option.value === currentValue

      if (renderOption) {
        return (
          <View
            key={option.value}
            className={classNames('ct-cascader__option', {
              'ct-cascader__option--selected': isSelected,
              'ct-cascader__option--disabled': option.disabled,
            })}
            onClick={() => handleOptionClick(option, level)}
          >
            {renderOption(option, isSelected)}
          </View>
        )
      }

      return (
        <View
          key={option.value}
          className={classNames('ct-cascader__option', {
            'ct-cascader__option--selected': isSelected,
            'ct-cascader__option--disabled': option.disabled,
          })}
          onClick={() => handleOptionClick(option, level)}
        >
          <Text className="ct-cascader__option-text">{option.label}</Text>
          {isSelected && (
            <Icon name="check" size={36} className="ct-cascader__option-icon" />
          )}
        </View>
      )
    })
  }

  return (
    <BottomSheet
      open={open}
      onClose={handleClose}
      className={classNames('ct-cascader', className)}
    >
      <View className="ct-cascader__header">
        <View className="ct-cascader__cancel" onClick={handleCancel}>
          <Text className="ct-cascader__cancel-text">{cancelText}</Text>
        </View>
        {title && <Text className="ct-cascader__title">{title}</Text>}
        <View className="ct-cascader__confirm" onClick={handleConfirm}>
          <Text className="ct-cascader__confirm-text">{confirmText}</Text>
        </View>
      </View>

      <ScrollView scrollX className="ct-cascader__tabs">
        {renderTabs()}
      </ScrollView>

      <View className="ct-cascader__content">
        {levelOptions.map((opts, level) => (
          <ScrollView
            key={level}
            scrollY
            className={classNames('ct-cascader__panel', {
              'ct-cascader__panel--active': level === activeLevel,
            })}
          >
            {renderOptions(opts, level)}
          </ScrollView>
        ))}
      </View>
    </BottomSheet>
  )
}

export default Cascader
export type { CascaderProps, CascaderOption } from './types'
