import { FC, useEffect, useState } from 'react'
import { ScrollView, Text, View } from '@tarojs/components'
import classNames from 'classnames'

/**
 * Types
 */
import type { IndexListProps } from './types'

import './index.scss'

export const IndexList: FC<IndexListProps> = ({
  data,
  current,
  sticky = true,
  stickyOffset = 0,
  onIndexChange,
  onItemClick,
  className,
}) => {
  /**
   * States
   */
  const [activeAnchor, setActiveAnchor] = useState(current || data[0]?.anchor)
  const [scrollIntoView, setScrollIntoView] = useState<string>()

  /**
   * Callbacks
   */
  const handleAnchorClick = (anchor: string) => {
    setActiveAnchor(anchor)
    setScrollIntoView(`ct-index-list-anchor-${anchor}`)
    onIndexChange?.(anchor)
  }

  /**
   * Effects
   */
  useEffect(() => {
    if (current !== undefined) {
      setActiveAnchor(current)
      setScrollIntoView(`ct-index-list-anchor-${current}`)
    }
  }, [current])

  return (
    <View className={classNames('ct-index-list', className)}>
      <ScrollView
        className="ct-index-list__content"
        scrollY
        scrollIntoView={scrollIntoView}
      >
        {data.map((group) => (
          <View
            key={group.anchor}
            className="ct-index-list__group"
            id={`ct-index-list-anchor-${group.anchor}`}
          >
            <View
              className={classNames('ct-index-list__anchor', {
                'ct-index-list__anchor--sticky': sticky,
              })}
              style={sticky ? { top: `${stickyOffset}px` } : undefined}
            >
              <Text>{group.anchor}</Text>
            </View>
            {group.items.map((item, index) => (
              <View
                key={index}
                className="ct-index-list__item"
                hoverClass="ct-clickable--hover"
                onClick={() => onItemClick?.(item, group.anchor)}
              >
                <Text>{item.text}</Text>
              </View>
            ))}
          </View>
        ))}
      </ScrollView>

      <View className="ct-index-list__sidebar">
        {data.map((group) => (
          <View
            key={group.anchor}
            className={classNames('ct-index-list__index', {
              'ct-index-list__index--active': activeAnchor === group.anchor,
            })}
            hoverClass="ct-clickable--hover"
            onClick={() => handleAnchorClick(group.anchor)}
          >
            <Text>{group.anchor}</Text>
          </View>
        ))}
      </View>
    </View>
  )
}

export default IndexList
export type { IndexListProps, IndexListItem } from './types'
