import type { CSSProperties } from 'react'
import { FC, useEffect, useState } from 'react'
import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { OVERLAY_ANIMATION_DURATION } from '../../constants/animation'
import { Icon } from '../icon'

/**
 * Types
 */
import type { BottomSheetProps } from './types'

import './index.scss'

export const BottomSheet: FC<BottomSheetProps> = ({
  open,
  title,
  description,
  onClose,
  showHandle = true,
  closable = false,
  closeOnOverlayClick = true,
  height = 'auto',
  children,
  className,
}) => {
  /**
   * States
   */
  const [visible, setVisible] = useState(false)
  const [animating, setAnimating] = useState(false)

  /**
   * Callbacks
   */
  const handleOverlayClick = () => {
    if (closeOnOverlayClick) {
      onClose?.()
    }
  }

  /**
   * Render Helpers
   */
  const getHeightStyle = (): CSSProperties => {
    if (height === 'auto') return {}
    if (height === 'full') return { height: '100vh' }
    return { height: `${height}rpx` }
  }

  /**
   * Effects
   */
  useEffect(() => {
    if (open) {
      setVisible(true)
      Taro.nextTick(() => setAnimating(true))
    } else {
      setAnimating(false)
      const timer = setTimeout(() => setVisible(false), OVERLAY_ANIMATION_DURATION)
      return () => clearTimeout(timer)
    }
    return undefined
  }, [open])

  /**
   * Early Returns
   */
  if (!visible) return null

  return (
    <View className="ct-bottom-sheet" catchMove>
      <View
        className={classNames('ct-bottom-sheet__mask', {
          'ct-bottom-sheet__mask--visible': animating,
        })}
        onClick={handleOverlayClick}
      />
      <View
        className={classNames(
          'ct-bottom-sheet__container',
          { 'ct-bottom-sheet__container--visible': animating },
          className
        )}
        style={getHeightStyle()}
      >
        {showHandle && (
          <View className="ct-bottom-sheet__handle" onClick={onClose} />
        )}

        {(title || closable) && (
          <View className="ct-bottom-sheet__header">
            <View className="ct-bottom-sheet__header-content">
              {title && <Text className="ct-bottom-sheet__title">{title}</Text>}
              {description && (
                <Text className="ct-bottom-sheet__description">{description}</Text>
              )}
            </View>
            {closable && (
              <View className="ct-bottom-sheet__close" onClick={onClose}>
                <Icon name="close" size={40} />
              </View>
            )}
          </View>
        )}

        <View className="ct-bottom-sheet__body">{children}</View>
      </View>
    </View>
  )
}

export default BottomSheet
export type { BottomSheetProps } from './types'
