import { FC, Fragment, useMemo, useState } from 'react'
import { Text, View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { Icon } from '../icon'

/**
 * Types
 */
import type { BreadcrumbItem, BreadcrumbProps } from './types'

import './index.scss'

export const Breadcrumb: FC<BreadcrumbProps> = ({
  items,
  separator,
  maxItems = 0,
  itemsBeforeCollapse = 1,
  itemsAfterCollapse = 1,
  onItemClick,
  className,
  style,
}) => {
  /**
   * States
   */
  const [showCollapsed, setShowCollapsed] = useState(false)

  /**
   * Derived Values
   */
  const { visibleItems, collapsedItems, shouldCollapse, collapseIndex } = useMemo(() => {
    if (maxItems <= 0 || items.length <= maxItems) {
      return {
        visibleItems: items,
        collapsedItems: [],
        shouldCollapse: false,
        collapseIndex: -1,
      }
    }

    const before = items.slice(0, itemsBeforeCollapse)
    const after = items.slice(-itemsAfterCollapse)
    const collapsed = items.slice(itemsBeforeCollapse, items.length - itemsAfterCollapse)

    return {
      visibleItems: [...before, ...after],
      collapsedItems: collapsed,
      shouldCollapse: true,
      collapseIndex: itemsBeforeCollapse,
    }
  }, [items, maxItems, itemsBeforeCollapse, itemsAfterCollapse])

  /**
   * Callbacks
   */
  const handleItemClick = (item: BreadcrumbItem, index: number, isLast: boolean) => {
    if (item.disabled || isLast) return

    if (onItemClick) {
      onItemClick(item, index)
    } else if (item.path) {
      Taro.navigateTo({ url: item.path }).catch(() => {
        Taro.redirectTo({ url: item.path! })
      })
    }
  }

  const handleCollapsedItemClick = (item: BreadcrumbItem, originalIndex: number) => {
    setShowCollapsed(false)
    if (item.disabled) return

    if (onItemClick) {
      onItemClick(item, originalIndex)
    } else if (item.path) {
      Taro.navigateTo({ url: item.path }).catch(() => {
        Taro.redirectTo({ url: item.path! })
      })
    }
  }

  /**
   * Render Helpers
   */
  const renderSeparator = () => (
    <View className="ct-breadcrumb__separator">
      {separator || <Icon name="chevron-right" size={24} />}
    </View>
  )

  const renderItem = (item: BreadcrumbItem, index: number, isLast: boolean) => {
    const isClickable = !isLast && !item.disabled && (item.path || onItemClick)

    return (
      <View
        key={index}
        className={classNames('ct-breadcrumb__item', {
          'ct-breadcrumb__item--current': isLast,
          'ct-breadcrumb__item--disabled': item.disabled,
          'ct-breadcrumb__item--clickable': isClickable,
        })}
        onClick={() => handleItemClick(item, index, isLast)}
        hoverClass={isClickable ? 'ct-breadcrumb__item--hover' : 'none'}
      >
        {item.icon && <View className="ct-breadcrumb__icon">{item.icon}</View>}
        <Text className="ct-breadcrumb__label">{item.label}</Text>
      </View>
    )
  }

  const renderEllipsis = () => (
    <View className="ct-breadcrumb__ellipsis-wrapper">
      <View
        className={classNames('ct-breadcrumb__ellipsis', {
          'ct-breadcrumb__ellipsis--active': showCollapsed,
        })}
        onClick={() => setShowCollapsed(!showCollapsed)}
        hoverClass="ct-breadcrumb__ellipsis--hover"
      >
        <Icon name="more-horizontal" size={32} />
      </View>

      {showCollapsed && (
        <>
          <View className="ct-breadcrumb__mask" onClick={() => setShowCollapsed(false)} />
          <View className="ct-breadcrumb__dropdown">
            {collapsedItems.map((item, idx) => {
              const originalIndex = itemsBeforeCollapse + idx
              return (
                <View
                  key={originalIndex}
                  className={classNames('ct-breadcrumb__dropdown-item', {
                    'ct-breadcrumb__dropdown-item--disabled': item.disabled,
                  })}
                  onClick={() => handleCollapsedItemClick(item, originalIndex)}
                  hoverClass={item.disabled ? 'none' : 'ct-breadcrumb__dropdown-item--hover'}
                >
                  {item.icon && <View className="ct-breadcrumb__dropdown-icon">{item.icon}</View>}
                  <Text className="ct-breadcrumb__dropdown-label">{item.label}</Text>
                </View>
              )
            })}
          </View>
        </>
      )}
    </View>
  )

  const renderItems = () => {
    const result: React.ReactNode[] = []

    visibleItems.forEach((item, idx) => {
      const isLastVisible = idx === visibleItems.length - 1
      const originalIndex = idx < itemsBeforeCollapse
        ? idx
        : items.length - itemsAfterCollapse + (idx - itemsBeforeCollapse)

      result.push(
        <Fragment key={`item-${originalIndex}`}>
          {renderItem(item, originalIndex, isLastVisible)}
        </Fragment>
      )

      if (shouldCollapse && idx === itemsBeforeCollapse - 1) {
        result.push(
          <Fragment key="sep-before-ellipsis">
            {renderSeparator()}
          </Fragment>
        )
        result.push(
          <Fragment key="ellipsis">
            {renderEllipsis()}
          </Fragment>
        )
      }

      if (!isLastVisible) {
        result.push(
          <Fragment key={`sep-${originalIndex}`}>
            {renderSeparator()}
          </Fragment>
        )
      }
    })

    return result
  }

  return (
    <View className={classNames('ct-breadcrumb', className)} style={style}>
      {renderItems()}
    </View>
  )
}

export default Breadcrumb
export type { BreadcrumbProps, BreadcrumbItem } from './types'
