import { FC } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { Icon } from '../icon'

/**
 * Types
 */
import type { StepStatus, StepsProps } from './types'

import './index.scss'

/**
 * Helpers
 */
const getStepStatus = (
  index: number,
  current: number,
  itemStatus?: StepStatus,
): StepStatus => {
  if (itemStatus) return itemStatus
  if (index < current) return 'finish'
  if (index === current) return 'process'
  return 'wait'
}

export const Steps: FC<StepsProps> = ({
  current,
  items,
  direction = 'horizontal',
  dot = false,
  onChange,
  className,
}) => {
  /**
   * Callbacks
   */
  const handleStepClick = (index: number) => {
    onChange?.(index)
  }

  return (
    <View
      className={classNames(
        'ct-steps',
        `ct-steps--${direction}`,
        { 'ct-steps--dot': dot },
        className,
      )}
    >
      {items.map((item, index) => {
        const status = getStepStatus(index, current, item.status)
        const isLast = index === items.length - 1

        return (
          <View
            key={index}
            className={classNames('ct-steps__item', `ct-steps__item--${status}`)}
            onClick={() => handleStepClick(index)}
          >
            <View className="ct-steps__icon-wrapper">
              {dot ? (
                <View className="ct-steps__dot" />
              ) : item.icon ? (
                <View className="ct-steps__icon">{item.icon}</View>
              ) : status === 'finish' ? (
                <View className="ct-steps__icon">
                  <Icon name="check" size={28} color="#fff" />
                </View>
              ) : status === 'error' ? (
                <View className="ct-steps__icon">
                  <Icon name="close" size={28} color="#fff" />
                </View>
              ) : (
                <View className="ct-steps__number">
                  <Text>{index + 1}</Text>
                </View>
              )}
            </View>

            {!isLast && <View className="ct-steps__line" />}

            <View className="ct-steps__content">
              <View className="ct-steps__title">
                <Text>{item.title}</Text>
              </View>
              {item.description && (
                <View className="ct-steps__description">
                  <Text>{item.description}</Text>
                </View>
              )}
            </View>
          </View>
        )
      })}
    </View>
  )
}

export default Steps
export type { StepsProps, StepItem, StepStatus, StepsDirection } from './types'
