import { FC } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'

/**
 * Types
 */
import type { BadgeProps } from './types'

import './index.scss'

export const Badge: FC<BadgeProps> = ({
  content,
  max = 99,
  dot = false,
  color,
  wrapper = true,
  children,
  className,
}) => {
  /**
   * Derived Values
   */
  const badgeStyle = color ? { backgroundColor: color } : undefined

  /**
   * Render Helpers
   */
  const renderContent = () => {
    if (dot) return null
    if (typeof content === 'number' && max && content > max) {
      return `${max}+`
    }
    return content
  }

  const badge = (content !== undefined || dot) && (
    <View
      className={classNames(
        'ct-badge__badge',
        {
          'ct-badge__badge--dot': dot,
        },
        (!wrapper || !children) && className
      )}
      style={badgeStyle}
    >
      {!dot && <Text className="ct-badge__text">{renderContent()}</Text>}
    </View>
  )

  /**
   * Early Returns
   */
  if (!wrapper || !children) {
    return badge || null
  }

  return (
    <View className={classNames('ct-badge', className)}>
      {children}
      {badge}
    </View>
  )
}

export default Badge
export type { BadgeProps } from './types'
