import { FC, useEffect, useRef, useState } from 'react'
import { View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'

/**
 * Types
 */
import type { PopoverAction, PopoverProps } from './types'

import './index.scss'

export const Popover: FC<PopoverProps> = ({
  open,
  defaultOpen = false,
  onOpenChange,
  actions = [],
  onSelect,
  placement = 'bottom',
  trigger = 'click',
  children,
  content,
  overlay = false,
  closeOnOverlayClick = true,
  closeOnSelect = true,
  theme = 'light',
  offset = [0, 8],
  className,
}) => {
  /**
   * Hooks
   */
  const [isOpen, setIsOpen] = useControllable({
    value: open,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })

  /**
   * Refs
   */
  const triggerRef = useRef<string>(`popover-trigger-${Date.now()}`)

  /**
   * States
   */
  const [position, setPosition] = useState({ top: 0, left: 0 })

  /**
   * Callbacks
   */
  const calculatePosition = () => {
    const query = Taro.createSelectorQuery()
    query.select(`#${triggerRef.current}`).boundingClientRect()
    query.selectViewport().scrollOffset()
    query.exec((res) => {
      if (!res[0]) return

      const rect = res[0]
      const scrollTop = res[1]?.scrollTop || 0
      const [offsetX, offsetY] = offset

      let top = 0
      let left = 0

      if (placement.startsWith('top')) {
        top = rect.top + scrollTop - offsetY
      } else if (placement.startsWith('bottom')) {
        top = rect.bottom + scrollTop + offsetY
      } else if (placement.startsWith('left')) {
        left = rect.left - offsetX
        top = rect.top + scrollTop + rect.height / 2
      } else if (placement.startsWith('right')) {
        left = rect.right + offsetX
        top = rect.top + scrollTop + rect.height / 2
      }

      if (placement.includes('-start')) {
        left = rect.left + offsetX
      } else if (placement.includes('-end')) {
        left = rect.right - offsetX
      } else if (placement === 'top' || placement === 'bottom') {
        left = rect.left + rect.width / 2
      }

      setPosition({ top, left })
    })
  }

  const handleTriggerClick = () => {
    if (trigger === 'click') {
      setIsOpen(!isOpen)
    }
  }

  const handleOverlayClick = () => {
    if (closeOnOverlayClick) {
      setIsOpen(false)
    }
  }

  const handleSelect = (action: PopoverAction, index: number) => {
    if (action.disabled) return
    onSelect?.(action, index)
    if (closeOnSelect) {
      setIsOpen(false)
    }
  }

  /**
   * Effects
   */
  useEffect(() => {
    if (isOpen) {
      calculatePosition()
    }
  }, [children, isOpen, offset, placement])

  useEffect(() => {
    if (!isOpen) return undefined
    const handleUpdate = () => calculatePosition()
    if (Taro.onWindowResize) {
      Taro.onWindowResize(handleUpdate)
    }
    if (typeof window !== 'undefined') {
      window.addEventListener('scroll', handleUpdate, true)
      window.addEventListener('resize', handleUpdate)
    }
    return () => {
      Taro.offWindowResize?.(handleUpdate)
      if (typeof window !== 'undefined') {
        window.removeEventListener('scroll', handleUpdate, true)
        window.removeEventListener('resize', handleUpdate)
      }
    }
  }, [isOpen, offset, placement])

  return (
    <View className={classNames('ct-popover', className)}>
      <View
        id={triggerRef.current}
        className="ct-popover__trigger"
        onClick={handleTriggerClick}
      >
        {children}
      </View>

      {isOpen && overlay && (
        <View className="ct-popover__overlay" onClick={handleOverlayClick} />
      )}

      {isOpen && (
        <View
          className={classNames(
            'ct-popover__content',
            `ct-popover__content--${placement}`,
            `ct-popover__content--${theme}`,
          )}
          style={{
            top: `${position.top}px`,
            left: `${position.left}px`,
          }}
        >
          <View className="ct-popover__arrow" />

          {content ? (
            <View className="ct-popover__body">{content}</View>
          ) : (
            <View className="ct-popover__actions">
              {actions.map((action, index) => (
                <View
                  key={index}
                  className={classNames('ct-popover__action', {
                    'ct-popover__action--disabled': action.disabled,
                  })}
                  style={action.color ? { color: action.color } : undefined}
                  onClick={() => handleSelect(action, index)}
                >
                  {action.icon && (
                    <View className="ct-popover__action-icon">
                      {action.icon}
                    </View>
                  )}
                  <View className="ct-popover__action-text">
                    {action.text}
                  </View>
                </View>
              ))}
            </View>
          )}
        </View>
      )}
    </View>
  )
}

export default Popover
export type {
  PopoverProps,
  PopoverAction,
  PopoverPlacement,
  PopoverTrigger,
} from './types'
