import { useEffect, useState } from 'react'
import Taro from '@tarojs/taro'
import { OVERLAY_ANIMATION_DURATION } from '../constants/animation'

/**
 * Types
 */
export interface UseOverlayAnimationOptions {
  open: boolean
  duration?: number
}

/**
 * Main Hook
 */
export function useOverlayAnimation({
  open,
  duration = OVERLAY_ANIMATION_DURATION,
}: UseOverlayAnimationOptions) {
  /**
   * States
   */
  const [visible, setVisible] = useState(false)
  const [animating, setAnimating] = useState(false)

  /**
   * Effects
   */
  useEffect(() => {
    if (open) {
      setVisible(true)
      Taro.nextTick(() => {
        setAnimating(true)
      })
    } else {
      setAnimating(false)
      const timer = setTimeout(() => {
        setVisible(false)
      }, duration)
      return () => clearTimeout(timer)
    }
    return undefined
  }, [open, duration])

  return { visible, animating }
}
