import { FC } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { Icon } from '../icon'

/**
 * Types
 */
import type { ListItemProps, ListProps } from './types'

import './index.scss'

/**
 * Sub Components
 */
export const ListItem: FC<ListItemProps> = ({
  title,
  description,
  prefix,
  extra,
  arrow = false,
  disabled = false,
  clickable = false,
  onClick,
  children,
  className,
}) => {
  /**
   * Derived Values
   */
  const isClickable = clickable || arrow || !!onClick

  return (
    <View
      className={classNames(
        'ct-list-item',
        {
          'ct-list-item--disabled': disabled,
          'ct-list-item--clickable': isClickable,
        },
        className,
      )}
      hoverClass={isClickable && !disabled ? 'ct-clickable--hover' : 'none'}
      onClick={disabled ? undefined : onClick}
    >
      {prefix && <View className="ct-list-item__prefix">{prefix}</View>}

      <View className="ct-list-item__content">
        {title && (
          <View className="ct-list-item__title">
            {typeof title === 'string' ? <Text>{title}</Text> : title}
          </View>
        )}
        {description && (
          <View className="ct-list-item__description">
            {typeof description === 'string' ? (
              <Text>{description}</Text>
            ) : (
              description
            )}
          </View>
        )}
        {children}
      </View>

      {extra && <View className="ct-list-item__extra">{extra}</View>}

      {arrow && (
        <View className="ct-list-item__arrow">
          <Icon name="arrow-right" size={32} color="var(--ct-color-text-tertiary)" />
        </View>
      )}
    </View>
  )
}

/**
 * Internal Types
 */
type ListComponent = FC<ListProps> & {
  Item: FC<ListItemProps>
}

/**
 * Main Component
 */
export const List: ListComponent = ({
  header,
  footer,
  bordered = true,
  children,
  className,
}) => {
  return (
    <View
      className={classNames(
        'ct-list',
        { 'ct-list--bordered': bordered },
        className,
      )}
    >
      {header && <View className="ct-list__header">{header}</View>}
      <View className="ct-list__body">{children}</View>
      {footer && <View className="ct-list__footer">{footer}</View>}
    </View>
  )
}

List.Item = ListItem

export default List
export type { ListProps, ListItemProps } from './types'
