import { FC } from 'react'
import { Image, Text, View } from '@tarojs/components'
import classNames from 'classnames'

/**
 * Types
 */
import type { CardProps } from './types'

import './index.scss'

export const Card: FC<CardProps> = ({
  title,
  subtitle,
  extra,
  cover,
  footer,
  bordered = true,
  shadow = false,
  headerDivider = true,
  clickable = false,
  onClick,
  className,
  children,
}) => {
  /**
   * Derived Values
   */
  const isClickable = clickable || !!onClick

  /**
   * Callbacks
   */
  const handleClick = () => {
    if (isClickable) {
      onClick?.()
    }
  }

  return (
    <View
      className={classNames(
        'ct-card',
        {
          'ct-card--bordered': bordered,
          'ct-card--shadow': shadow,
          'ct-card--clickable': isClickable,
        },
        className
      )}
      onClick={handleClick}
      hoverClass={isClickable ? 'ct-card--hover' : 'none'}
    >
      {cover && (
        <View className="ct-card__cover">
          <Image className="ct-card__cover-image" src={cover} mode="aspectFill" />
        </View>
      )}

      {(title || extra) && (
        <View
          className={classNames('ct-card__header', {
            'ct-card__header--no-divider': !headerDivider,
          })}
        >
          <View className="ct-card__header-content">
            {title && <Text className="ct-card__title">{title}</Text>}
            {subtitle && <Text className="ct-card__subtitle">{subtitle}</Text>}
          </View>
          {extra && <View className="ct-card__extra">{extra}</View>}
        </View>
      )}

      {children && <View className="ct-card__body">{children}</View>}

      {footer && <View className="ct-card__footer">{footer}</View>}
    </View>
  )
}

export default Card
export type { CardProps } from './types'
