import { FC, useState } from 'react'
import { Text, Textarea as TaroTextarea, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'

/**
 * Types
 */
import type { TextareaProps } from './types'

import './index.scss'

export const Textarea: FC<TextareaProps> = ({
  value: propValue,
  defaultValue = '',
  placeholder,
  disabled = false,
  maxLength,
  showCount = false,
  autoHeight = false,
  rows = 3,
  onChange,
  onFocus,
  onBlur,
  className,
}) => {
  /**
   * Hooks
   */
  const [value, setValue] = useControllable({
    value: propValue,
    defaultValue,
    onChange,
  })

  /**
   * States
   */
  const [focused, setFocused] = useState(false)

  /**
   * Callbacks
   */
  const handleInput = (e: any) => setValue(e.detail.value)

  const handleFocus = (e: any) => {
    setFocused(true)
    onFocus?.(e)
  }

  const handleBlur = (e: any) => {
    setFocused(false)
    onBlur?.(e)
  }

  return (
    <View
      className={classNames(
        'ct-textarea',
        {
          'ct-textarea--disabled': disabled,
          'ct-textarea--focused': focused,
          'ct-textarea--with-count': showCount,
        },
        className
      )}
    >
      <TaroTextarea
        className="ct-textarea__inner"
        style={
          !autoHeight
            ? { minHeight: `${rows * 42}rpx` }
            : undefined
        }
        value={value}
        placeholder={placeholder}
        disabled={disabled}
        maxlength={maxLength}
        autoHeight={autoHeight}
        onInput={handleInput}
        onFocus={handleFocus}
        onBlur={handleBlur}
      />

      {showCount && (
        <View className="ct-textarea__count">
          <Text>
            {value.length}
            {maxLength && `/${maxLength}`}
          </Text>
        </View>
      )}
    </View>
  )
}

export default Textarea
export type { TextareaProps } from './types'
