import { FC, useState } from 'react'
import { ScrollView, Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { Loading } from '../loading'

/**
 * Types
 */
import type { InfiniteScrollProps } from './types'

import './index.scss'

/**
 * Main Component
 */
export const InfiniteScroll: FC<InfiniteScrollProps> = ({
  hasMore,
  loading = false,
  threshold = 100,
  scrollable = true,
  onLoadMore,
  loadingText = '加载中...',
  finishedText = '没有更多了',
  loadingContent,
  finishedContent,
  children,
  className,
}) => {
  /**
   * States
   */
  const [isLoading, setIsLoading] = useState(false)

  /**
   * Callbacks
   */
  const handleScrollToLower = async () => {
    if (loading || isLoading || !hasMore) return

    setIsLoading(true)
    try {
      await onLoadMore()
    } finally {
      setIsLoading(false)
    }
  }

  /**
   * Render Helpers
   */
  const content = (
    <>
      {children}

      <View className="ct-infinite-scroll__footer">
        {(loading || isLoading) &&
          hasMore &&
          (loadingContent || (
            <View className="ct-infinite-scroll__loading">
              <Loading type="spinner" size="sm" />
              <Text className="ct-infinite-scroll__text">{loadingText}</Text>
            </View>
          ))}

        {!hasMore &&
          (finishedContent || (
            <View className="ct-infinite-scroll__finished">
              <Text className="ct-infinite-scroll__text">{finishedText}</Text>
            </View>
          ))}
      </View>
    </>
  )

  /**
   * Early Returns
   */
  if (!scrollable) {
    return (
      <View className={classNames('ct-infinite-scroll', className)}>
        {content}
      </View>
    )
  }

  return (
    <ScrollView
      className={classNames('ct-infinite-scroll', className)}
      scrollY
      lowerThreshold={threshold}
      onScrollToLower={handleScrollToLower}
    >
      {content}
    </ScrollView>
  )
}

export default InfiniteScroll
export type { InfiniteScrollProps } from './types'
