import { FC, useCallback, useMemo, useState } from 'react'
import { Input, Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { Icon } from '../icon'

/**
 * Types
 */
import type { PaginationProps } from './types'

import './index.scss'

export const Pagination: FC<PaginationProps> = ({
  current: propCurrent,
  defaultCurrent = 1,
  total,
  pageSize = 10,
  mode = 'simple',
  showTotal = false,
  showQuickJumper = false,
  disabled = false,
  onChange,
  prevText,
  nextText,
  className,
  style,
}) => {
  /**
   * Derived Values
   */
  const isControlled = propCurrent !== undefined

  /**
   * States
   */
  const [innerCurrent, setInnerCurrent] = useState(defaultCurrent)
  const [jumpValue, setJumpValue] = useState('')

  /**
   * Derived Values
   */
  const current = isControlled ? propCurrent : innerCurrent

  const totalPages = useMemo(() => {
    return Math.max(1, Math.ceil(total / pageSize))
  }, [total, pageSize])

  const range = useMemo((): [number, number] => {
    const start = (current - 1) * pageSize + 1
    const end = Math.min(current * pageSize, total)
    return [start, end]
  }, [current, pageSize, total])

  const pageButtons = useMemo(() => {
    if (mode !== 'default') return []

    const buttons: (number | 'prev' | 'next')[] = []
    const maxButtons = 5

    if (totalPages <= maxButtons + 2) {
      for (let i = 1; i <= totalPages; i++) {
        buttons.push(i)
      }
    } else {
      buttons.push(1)

      if (current > 3) {
        buttons.push('prev')
      }

      let start = Math.max(2, current - 1)
      let end = Math.min(totalPages - 1, current + 1)

      if (current <= 3) {
        end = Math.min(totalPages - 1, maxButtons - 1)
      }

      if (current >= totalPages - 2) {
        start = Math.max(2, totalPages - maxButtons + 2)
      }

      for (let i = start; i <= end; i++) {
        buttons.push(i)
      }

      if (current < totalPages - 2) {
        buttons.push('next')
      }

      buttons.push(totalPages)
    }

    return buttons
  }, [current, totalPages, mode])

  /**
   * Callbacks
   */
  const handleChange = useCallback((page: number) => {
    const validPage = Math.max(1, Math.min(page, totalPages))
    if (validPage === current || disabled) return

    if (!isControlled) {
      setInnerCurrent(validPage)
    }
    onChange?.(validPage, pageSize)
  }, [current, totalPages, isControlled, pageSize, onChange, disabled])

  const handlePrev = () => {
    if (current > 1) {
      handleChange(current - 1)
    }
  }

  const handleNext = () => {
    if (current < totalPages) {
      handleChange(current + 1)
    }
  }

  const handleJump = () => {
    const page = parseInt(jumpValue, 10)
    if (!isNaN(page)) {
      handleChange(page)
    }
    setJumpValue('')
  }

  /**
   * Render Helpers
   */
  const renderTotal = () => {
    if (!showTotal) return null

    const content = typeof showTotal === 'function'
      ? showTotal(total, range)
      : `共 ${total} 条`

    return (
      <View className="ct-pagination__total">
        <Text>{content}</Text>
      </View>
    )
  }

  const renderSimple = () => (
    <>
      <View
        className={classNames('ct-pagination__btn', {
          'ct-pagination__btn--disabled': current <= 1 || disabled,
        })}
        onClick={handlePrev}
        hoverClass={current <= 1 || disabled ? 'none' : 'ct-pagination__btn--hover'}
      >
        {prevText || <Icon name="chevron-left" size={40} />}
      </View>

      <View className="ct-pagination__info">
        <Text className="ct-pagination__current">{current}</Text>
        <Text className="ct-pagination__divider">/</Text>
        <Text className="ct-pagination__pages">{totalPages}</Text>
      </View>

      <View
        className={classNames('ct-pagination__btn', {
          'ct-pagination__btn--disabled': current >= totalPages || disabled,
        })}
        onClick={handleNext}
        hoverClass={current >= totalPages || disabled ? 'none' : 'ct-pagination__btn--hover'}
      >
        {nextText || <Icon name="chevron-right" size={40} />}
      </View>
    </>
  )

  const renderMini = () => (
    <>
      <View
        className={classNames('ct-pagination__btn ct-pagination__btn--mini', {
          'ct-pagination__btn--disabled': current <= 1 || disabled,
        })}
        onClick={handlePrev}
        hoverClass={current <= 1 || disabled ? 'none' : 'ct-pagination__btn--hover'}
      >
        <Icon name="chevron-left" size={32} />
      </View>

      <Text className="ct-pagination__text-mini">{current}/{totalPages}</Text>

      <View
        className={classNames('ct-pagination__btn ct-pagination__btn--mini', {
          'ct-pagination__btn--disabled': current >= totalPages || disabled,
        })}
        onClick={handleNext}
        hoverClass={current >= totalPages || disabled ? 'none' : 'ct-pagination__btn--hover'}
      >
        <Icon name="chevron-right" size={32} />
      </View>
    </>
  )

  const renderDefault = () => (
    <>
      <View
        className={classNames('ct-pagination__btn', {
          'ct-pagination__btn--disabled': current <= 1 || disabled,
        })}
        onClick={handlePrev}
        hoverClass={current <= 1 || disabled ? 'none' : 'ct-pagination__btn--hover'}
      >
        {prevText || <Icon name="chevron-left" size={40} />}
      </View>

      <View className="ct-pagination__pages-wrapper">
        {pageButtons.map((item, index) => {
          if (item === 'prev') {
            return (
              <View
                key="prev-ellipsis"
                className="ct-pagination__ellipsis"
                onClick={() => handleChange(Math.max(1, current - 5))}
                hoverClass="ct-pagination__ellipsis--hover"
              >
                <Icon name="more-horizontal" size={32} />
              </View>
            )
          }

          if (item === 'next') {
            return (
              <View
                key="next-ellipsis"
                className="ct-pagination__ellipsis"
                onClick={() => handleChange(Math.min(totalPages, current + 5))}
                hoverClass="ct-pagination__ellipsis--hover"
              >
                <Icon name="more-horizontal" size={32} />
              </View>
            )
          }

          return (
            <View
              key={item}
              className={classNames('ct-pagination__page', {
                'ct-pagination__page--active': item === current,
                'ct-pagination__page--disabled': disabled,
              })}
              onClick={() => handleChange(item)}
              hoverClass={disabled ? 'none' : 'ct-pagination__page--hover'}
            >
              <Text>{item}</Text>
            </View>
          )
        })}
      </View>

      <View
        className={classNames('ct-pagination__btn', {
          'ct-pagination__btn--disabled': current >= totalPages || disabled,
        })}
        onClick={handleNext}
        hoverClass={current >= totalPages || disabled ? 'none' : 'ct-pagination__btn--hover'}
      >
        {nextText || <Icon name="chevron-right" size={40} />}
      </View>
    </>
  )

  const renderQuickJumper = () => {
    if (!showQuickJumper || mode === 'mini') return null

    return (
      <View className="ct-pagination__jumper">
        <Text className="ct-pagination__jumper-text">跳至</Text>
        <Input
          className="ct-pagination__jumper-input"
          type="number"
          value={jumpValue}
          disabled={disabled}
          onInput={(e) => setJumpValue(e.detail.value)}
          onConfirm={handleJump}
          onBlur={handleJump}
        />
        <Text className="ct-pagination__jumper-text">页</Text>
      </View>
    )
  }

  return (
    <View
      className={classNames(
        'ct-pagination',
        `ct-pagination--${mode}`,
        { 'ct-pagination--disabled': disabled },
        className
      )}
      style={style}
    >
      {renderTotal()}

      <View className="ct-pagination__main">
        {mode === 'simple' && renderSimple()}
        {mode === 'mini' && renderMini()}
        {mode === 'default' && renderDefault()}
      </View>

      {renderQuickJumper()}
    </View>
  )
}

export default Pagination
export type { PaginationProps, PaginationMode } from './types'
