import { createContext, FC, useContext, useEffect, useMemo } from 'react'
import { View } from '@tarojs/components'
import Taro from '@tarojs/taro'
import zhCN from './locales/zh-CN'

/**
 * Types
 */
import type {
  ConfigContextValue,
  ConfigProviderProps,
  Locale,
  ThemeConfig,
} from './types'

/**
 * Constants
 */
const defaultTheme: ThemeConfig = {
  mode: 'light',
}

const defaultLocale: Locale = zhCN

/**
 * Context
 */
const ConfigContext = createContext<ConfigContextValue>({
  theme: defaultTheme,
  locale: defaultLocale,
})

/**
 * Hooks
 */
export const useConfig = () => useContext(ConfigContext)

/**
 * Main Component
 */
export const ConfigProvider: FC<ConfigProviderProps> = ({
  theme,
  locale,
  children,
}) => {
  /**
   * Derived Values
   */
  const mergedTheme = useMemo(
    () => ({
      ...defaultTheme,
      ...theme,
    }),
    [theme]
  )

  const mergedLocale = useMemo(
    () => ({
      ...defaultLocale,
      ...locale,
      common: { ...defaultLocale.common, ...locale?.common },
      calendar: { ...defaultLocale.calendar, ...locale?.calendar },
      picker: { ...defaultLocale.picker, ...locale?.picker },
      pullRefresh: { ...defaultLocale.pullRefresh, ...locale?.pullRefresh },
      infiniteScroll: { ...defaultLocale.infiniteScroll, ...locale?.infiniteScroll },
    }),
    [locale]
  )

  const contextValue = useMemo(
    () => ({
      theme: mergedTheme,
      locale: mergedLocale,
    }),
    [mergedTheme, mergedLocale]
  )

  /**
   * Effects
   */
  // 应用主题 CSS 变量
  useEffect(() => {
    const cssVars: Record<string, string> = {}

    if (mergedTheme.primaryColor) {
      cssVars['--ct-color-primary'] = mergedTheme.primaryColor
    }
    if (mergedTheme.successColor) {
      cssVars['--ct-color-success'] = mergedTheme.successColor
    }
    if (mergedTheme.warningColor) {
      cssVars['--ct-color-warning'] = mergedTheme.warningColor
    }
    if (mergedTheme.errorColor) {
      cssVars['--ct-color-error'] = mergedTheme.errorColor
    }

    // 在 Web 环境下设置 CSS 变量
    if (Taro.getEnv?.() === Taro.ENV_TYPE.WEB && typeof document !== 'undefined') {
      Object.entries(cssVars).forEach(([key, value]) => {
        document.documentElement.style.setProperty(key, value)
      })
    }
  }, [mergedTheme])

  // 处理深色模式
  useEffect(() => {
    if (Taro.getEnv?.() === Taro.ENV_TYPE.WEB && typeof document !== 'undefined') {
      const html = document.documentElement

      if (mergedTheme.mode === 'dark') {
        html.setAttribute('data-theme', 'dark')
      } else if (mergedTheme.mode === 'light') {
        html.removeAttribute('data-theme')
      } else if (mergedTheme.mode === 'system') {
        const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches
        if (prefersDark) {
          html.setAttribute('data-theme', 'dark')
        } else {
          html.removeAttribute('data-theme')
        }
      }
    }
  }, [mergedTheme.mode])

  return (
    <ConfigContext.Provider value={contextValue}>
      <View className="ct-config-provider">{children}</View>
    </ConfigContext.Provider>
  )
}

export default ConfigProvider
export { zhCN }
export type {
  ConfigContextValue,
  ConfigProviderProps,
  Locale,
  ThemeConfig,
  ThemeMode,
} from './types'
