import { FC, useCallback } from 'react'
import { ScrollView, Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Badge } from '../badge'

/**
 * Types
 */
import type { SideBarItem, SideBarProps } from './types'

import './index.scss'

export const SideBar: FC<SideBarProps> = ({
  items,
  activeKey,
  defaultActiveKey,
  onChange,
  className,
}) => {
  /**
   * Derived Values
   */
  const defaultKey = defaultActiveKey || items[0]?.key

  /**
   * Hooks
   */
  const [internalActiveKey, setInternalActiveKey] = useControllable({
    value: activeKey,
    defaultValue: defaultKey,
    onChange,
  })

  /**
   * Callbacks
   */
  const handleItemClick = useCallback(
    (item: SideBarItem) => {
      if (item.disabled) return
      setInternalActiveKey(item.key)
    },
    [setInternalActiveKey]
  )

  /**
   * Render Helpers
   */
  const renderItem = (item: SideBarItem) => {
    const isActive = internalActiveKey === item.key

    return (
      <View
        key={item.key}
        className={classNames('ct-sidebar__item', {
          'ct-sidebar__item--active': isActive,
          'ct-sidebar__item--disabled': item.disabled,
        })}
        onClick={() => handleItemClick(item)}
      >
        {isActive && <View className="ct-sidebar__item-indicator" />}
        <View className="ct-sidebar__item-content">
          {item.badge !== undefined ? (
            <Badge content={item.badge}>
              <Text className="ct-sidebar__item-title">{item.title}</Text>
            </Badge>
          ) : (
            <Text className="ct-sidebar__item-title">{item.title}</Text>
          )}
        </View>
      </View>
    )
  }

  return (
    <ScrollView scrollY className={classNames('ct-sidebar', className)}>
      {items.map(renderItem)}
    </ScrollView>
  )
}

export default SideBar
export type { SideBarProps, SideBarItem } from './types'
