import { FC } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { useControllable } from '../../hooks/useControllable'
import { Badge } from '../badge'

/**
 * Types
 */
import type { TabBarItem, TabBarProps } from './types'

import './index.scss'

export const TabBar: FC<TabBarProps> = ({
  activeKey: propActiveKey,
  defaultActiveKey,
  items,
  onChange,
  fixed = true,
  bordered = true,
  safeArea = true,
  className,
}) => {
  /**
   * Hooks
   */
  const [activeKey, setActiveKey] = useControllable({
    value: propActiveKey,
    defaultValue: defaultActiveKey || items[0]?.key,
    onChange,
  })

  /**
   * Callbacks
   */
  const handleItemClick = (item: TabBarItem) => {
    setActiveKey(item.key)
  }

  return (
    <>
      <View
        className={classNames(
          'ct-tabbar',
          {
            'ct-tabbar--fixed': fixed,
            'ct-tabbar--bordered': bordered,
            'ct-tabbar--safe-area': safeArea,
          },
          className,
        )}
      >
        {items.map((item) => {
          const isActive = activeKey === item.key

          return (
            <View
              key={item.key}
              className={classNames('ct-tabbar__item', {
                'ct-tabbar__item--active': isActive,
              })}
              onClick={() => handleItemClick(item)}
            >
              <View className="ct-tabbar__icon">
                {isActive && item.activeIcon ? item.activeIcon : item.icon}
                {(item.badge !== undefined || item.dot) && (
                  <Badge
                    content={item.badge}
                    dot={item.dot}
                    className="ct-tabbar__badge"
                  />
                )}
              </View>
              <Text className="ct-tabbar__title">{item.title}</Text>
            </View>
          )
        })}
      </View>

      {fixed && (
        <View
          className={classNames('ct-tabbar__placeholder', {
            'ct-tabbar__placeholder--safe-area': safeArea,
          })}
        />
      )}
    </>
  )
}

export default TabBar
export type { TabBarProps, TabBarItem } from './types'
