import { FC } from 'react'
import { Text, View } from '@tarojs/components'
import classNames from 'classnames'
import { Icon } from '../icon'

/**
 * Types
 */
import type { ResultProps, ResultStatus } from './types'

import './index.scss'

/**
 * Constants
 */
const STATUS_ICON: Record<ResultStatus, string> = {
  success: 'check-circle-fill',
  error: 'close-circle-fill',
  info: 'info-circle',
  warning: 'warning-circle',
  waiting: 'clock',
  '404': 'search',
  '403': 'close-circle',
  '500': 'close-circle-fill',
  offline: 'close-circle',
}

const STATUS_COLOR: Record<ResultStatus, string> = {
  success: 'var(--ct-color-success)',
  error: 'var(--ct-color-error)',
  info: 'var(--ct-color-primary)',
  warning: 'var(--ct-color-warning)',
  waiting: 'var(--ct-color-text-tertiary)',
  '404': 'var(--ct-color-text-tertiary)',
  '403': 'var(--ct-color-warning)',
  '500': 'var(--ct-color-error)',
  offline: 'var(--ct-color-text-tertiary)',
}

export const Result: FC<ResultProps> = ({
  status,
  title,
  description,
  icon,
  children,
  className,
}) => {
  return (
    <View className={classNames('ct-result', `ct-result--${status}`, className)}>
      <View className="ct-result__icon">
        {icon || (
          <Icon name={STATUS_ICON[status]} size={120} color={STATUS_COLOR[status]} />
        )}
      </View>

      <View className="ct-result__title">
        {typeof title === 'string' ? <Text>{title}</Text> : title}
      </View>

      {description && (
        <View className="ct-result__description">
          {typeof description === 'string' ? <Text>{description}</Text> : description}
        </View>
      )}

      {children && <View className="ct-result__actions">{children}</View>}
    </View>
  )
}

export default Result
export type { ResultProps, ResultStatus } from './types'
